35	    /** The sheet's periods by from-date. */
36	    @Transactional(readOnly = true)
37	    public List<Period> list(String sheetId) {
38	        sheets.today(sheetId); // the sheet must exist
39	        return periods.findBySheetIdOrderByFromAsc(sheetId);
40	    }
41	
42	    /** Add a period; one whose to-date is before its from-date, whose name is taken on the sheet, or that
43	     * overlaps another of the sheet's periods is refused. */
44	    @Transactional
45	    public Period add(String user, String sheetId, String name, LocalDate from, LocalDate to) {
46	        // Locking the sheet adds its periods one at a time, so two at once cannot overlap.
47	        sheets.lock(sheetId);
48	        String trimmed = name.trim();
49	        if (to.isBefore(from)) {
50	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
51	        }
52	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
53	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
54	        }
55	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
56	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
57	        }
58	        Period period;
59	        try {
60	            period = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
61	        } catch (DataIntegrityViolationException e) {
62	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
63	        }
64	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
65	                + " from=" + period.getFrom() + " to=" + period.getTo());
66	        return period;
67	    }
