70	    @Transactional
71	    public Period close(String user, String sheetId, Long id) {
72	        // Locking the sheet keeps claims from changing while the total is taken.
73	        sheets.lock(sheetId);
74	        Period period = periods.findByIdAndSheetId(id, sheetId)
75	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
76	        settings.requirePermitted(sheetId, user, Permission.CLOSE);
77	        if (period.isClosed()) {
78	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
79	        }
80	        period.close(rollup.dueTotals(sheetId, period.getFrom(), period.getTo()));
81	        periods.flush();
82	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
83	                + " total=" + period.getClosedTotal().toPlainString());
84	        return period;
85	    }
86	
87	    /** Reopen a closed period, making its due-total live again; only a role the permission matrix allows (a steward by the standing rule) may, and reopening one that is
88	     * open is refused. */
89	    @Transactional
90	    public Period reopen(String user, String sheetId, Long id) {
91	        sheets.lock(sheetId);
92	        Period period = periods.findByIdAndSheetId(id, sheetId)
93	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
94	        settings.requirePermitted(sheetId, user, Permission.REOPEN);
95	        if (!period.isClosed()) {
96	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
97	        }
98	        period.reopen();
99	        periods.flush();
100	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + period.getName());
101	        return period;
102	    }
103	
104	    /** The sheet's period a date is in, if any. */
105	    @Transactional(readOnly = true)
106	    public Optional<Period> periodOf(String sheetId, LocalDate date) {
107	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream().filter(p -> p.contains(date)).findFirst();
108	    }
109	
110	    /** Refuse a change to a claim dated in one of the sheet's closed periods. */
111	    @Transactional(readOnly = true)
112	    public void requireOpen(String sheetId, LocalDate date) {
113	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.isClosed() && p.contains(date))) {
114	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim is dated in a closed period.");
115	        }
116	    }
117	}
