      }
      froms[`${key}From`] = from;
    }
    const changed = {
      ...(sendLimit ? { clerkLimit } : {}),
      ...(sendFloor ? { floor } : {}),
      ...(sendTerms ? { terms } : {}),
      ...gradeTerms,
      ...(sendLatePct ? { latePct } : {}),
      ...(sendPolicyDate ? { policyDate } : {}),
      ...(sendPeriodNumbering ? { periodNumberingFrom } : {}),
      ...(sendCap ? { cap } : {}),
      ...(sendProofThreshold ? { proofThreshold } : {}),
      ...permissions,
      ...froms,
    };
    this.saves.next({ sheetId, changed, sent: this.settingsForm.getRawValue() });
  }

  /** Show the settings in force, and put them back in the form as unchanged; after a save (`sent` the form as
   * it was saved), a setting changed in the form since is left as it was typed. */
  private showSettings(s: SheetSettings, sent?: SettingsFormValue & Record<FromField, string>): void {
    this.settings.set(s);
    this.floor.set(s.dated.floor);
    this.latePct.set(s.dated['late-pct']);
    this.policyDate.set(s.policyDate);
    this.cap.set(s.dated.cap);
    const shown: SettingsFormValue = {
      clerkLimit: s.clerkLimit ?? '',
      floor: s.floor,
      terms: String(s.terms),
      termsA: s.termsA === null ? '' : String(s.termsA),
      termsB: s.termsB === null ? '' : String(s.termsB),
      termsC: s.termsC === null ? '' : String(s.termsC),
      latePct: s.latePct,
      policyDate: s.policyDate ?? '',
      periodNumberingFrom: s.periodNumberingFrom ?? '',
      cap: s.cap ?? '',
      proofThreshold: s.proofThreshold ?? '',
      ...(Object.fromEntries(PERMISSIONS.map((p) => [PERMISSION_FIELDS[p], s.permissions[p]])) as Record<
        PermissionField,
        string
      >),
    };
    const controls = this.settingsForm.controls;
    for (const key of Object.keys(shown) as (keyof SettingsFormValue)[]) {
      if (!sent || controls[key].value === sent[key]) controls[key].reset(shown[key], { emitEvent: false });
    }
    // A from-date goes with the save it was typed for: it is cleared, unless typed again since.
    for (const key of Object.keys(DATED_FIELDS) as DatedField[]) {
      const from = controls[`${key}From`];
      if (!sent || from.value === sent[`${key}From`]) from.reset('', { emitEvent: false });
    }
  }
}
  termsB: number | null;
  termsC: number | null;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) a claim dated before rounds half up, on or after half to even; null for the
   * sheet's today. */
  policyDate: string | null;
  /** The date (yyyy-mm-dd) from which, while the sheet's today is on or after it, a claim opened is numbered
   * within its period; null when off. */
  periodNumberingFrom: string | null;
  /** The most a person's due-total comes to, with two decimals; null for none. */
  cap: string | null;
  /** The due above which a claim needs a proof before it is settled or approved, with two decimals; null for
   * none. */
  proofThreshold: string | null;
  dated: Record<DatedKey, Dated[]>;
  /** By action, the roles that may take it, comma separated; blank keeps the standing rule. */
  permissions: Record<Permission, string>;
}

// A sheet's settings: the role each user name has, its clerk limit, its floor, its terms and each grade's, its late percent, its policy date, its period numbering date, its cap, its proof threshold (those that carry a figure dated) and its permission matrix, read and changed through the
// server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  roles(sheetId: string): Observable<RoleGiven[]> {
    return this.http.get<RoleGiven[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() });
  }

  setRole(sheetId: string, user: string, role: string): Observable<RoleGiven> {
    return this.http.put<RoleGiven>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() });
  }

  get(sheetId: string): Observable<Settings> {
    return this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() });
  }

  /** Save the settings given; one left out is left as it is. A setting that carries a figure is recorded from
   * its from-date (`floorFrom` and so on), or from the sheet's today when none is given. */
  save(
    sheetId: string,
    settings: { clerkLimit?: string; floor?: string; terms?: string; termsA?: string; termsB?: string;
      termsC?: string; latePct?: string; policyDate?: string; periodNumberingFrom?: string; cap?: string;
      proofThreshold?: string; clerkLimitFrom?: string; floorFrom?: string; termsFrom?: string; termsAFrom?: string; termsBFrom?: string;
      termsCFrom?: string; latePctFrom?: string; capFrom?: string; proofThresholdFrom?: string;
      permOpen?: string; permSettle?: string; permVoid?: string; permReassign?: string; permClose?: string;
      permReopen?: string; },
  ): Observable<Settings> {
    return this.http.put<Settings>(`${this.url(sheetId)}/settings`, settings, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

